            {  
                Log.Warn(\$"[GroupLock] 未抢到锁，Key={lockKey}");

                return new VipLotteryResult { IsSuccess = false, Msg = "请求频繁，请稍后再试" };

            }



            // 第四步：锁内 double-check

            int doneCount = groupOrderLogRepository.CountDoneByGroup(

                brandId, vipId, orderId, actInfo.GroupId.Value);



            if (doneCount >= actInfo.GroupMaxJoinCount)

            {

                return new VipLotteryResult { IsSuccess = false, Msg = "组内参与次数已满" };

            }



            // 第五步：发奖逻辑（在锁内执行，发奖成功后立即更新 IsLuckDraw=1）

            // ... 原有发奖逻辑 ...

        }

    }

    catch (Exception ex)

    {

        // Redis 连接异常：拒绝发奖，不降级为无锁执行

        Log.Error(\$"[GroupLock] Redis 异常，Key={lockKey}", ex);

        return new VipLotteryResult { IsSuccess = false, Msg = "系统繁忙，请稍后重试" };

    }

}

