**`ExecuteJob` 核心修改逻辑（仅新版 `IsPayActivityNew=true` 路径）：**

原有逻辑（保持不变）：

  过滤候选活动 → 逐活动校验 → 按优先级排序 → actModel = 取第1个



新增逻辑（在选出 actModel 后）：

  if (actModel.GroupId == null)

  {

      // 无组 → 原有单活动处理，写旧表（不变）

      ProcessSingleAct(actModel, ...);

  }

  else

  {

      // 有组 → 组内多活动处理，写新表

      ProcessGroupActs(actModel.GroupId, ...);

  }

**新增方法 `ProcessGroupActs`：**

/// <summary>

/// 有组活动处理：取组内所有活动，全套过滤后按MaxJoinCount取最终参与列表，写新表

/// </summary>

private void ProcessGroupActs(

    int brandId, int copId,

    PayActivityPaySuccessJobRequest request,

    MpActDeliverReferencedInfo entryAct)

{

    // 【P1-2 防御】分组功能仅限线下订单，商城订单直接返回

    if (request.OrderType == 0)

    {

        Log.Warn(\$"ProcessGroupActs: 商城订单不走分组路径，OrderId={request.OrderId}，GroupId={entryAct.GroupId}");

        return;

    }



    // 1. 获取组内所有活动（直接从已加载的全局列表按 GroupId 过滤，门槛数据一致，无额外 GRPC 调用）

    var groupActList = \_initBizData.\_ActList

        .FindAll(x => x.GroupId == entryAct.GroupId);



    if (groupActList == null || !groupActList.Any()) return;



    // 2. 门店是否营业（与具体活动无关，提前判断一次）

    bool isShopActive = EdBaseShopBll.IsShopActive(brandId, request.ShopId);



    // 3. 对每个活动走全套过滤

    var validActList = new List<MpActDeliverReferencedInfo>();

    foreach (var act in groupActList)

    {

        if (!isShopActive) break; // 门店无效，整组均不参与



        // 3.1 金额门槛 + 支付时间

        if (request.PayTime < act.BegDate || request.PayTime > act.EndDate

            || request.SalesAmount < act.SalesAmount)

            continue;



        // 3.2 消费门店归属

        if (!IsShopMatch(request.ShopId, act)) continue;



        // 3.3 会员参与门槛

        if (!CheckActThreshold(brandId, request.VipId, act)) continue;



        // 3.4 订单是否已参与（【P0-1 修正】纯校验，不写旧表）

        // 先查新表（分组活动记录在此），再查域服务（兜底）

        if (IsGroupOrderLogExists(brandId, request.VipId, request.OrderId, act.Id))

        {

            Log.Debug(\$"ProcessGroupActs: ActId={act.Id} 新表已有记录，跳过");  
            continue;  
        }  
        if (CheckActVipOrderChanceOnly(brandId, request, act))  
        {  
            Log.Debug(\$"ProcessGroupActs: ActId={act.Id} 域服务返回已参与，跳过");

            continue;

        }



        // 3.5 今日/累计次数是否达上限（【P1-1 修正】查新表+旧表合并统计）

        if (!CheckGroupActVipChance(brandId, request.VipId, act))

        {

            Log.Debug(\$"ProcessGroupActs: ActId={act.Id} 参与次数已达上限");

            continue;

        }



        // 3.6 货号校验

        if (!CheckItemNo(brandId, request, act)) continue;



        validActList.Add(act);

    }



    if (!validActList.Any()) return;



    // 4. 全量写入：按优先级排序，但不截断（MaxJoinCount 限制在 GetDeliverInfo 和 VipLotteryBll 处执行）

    // IsAllJoin=true：直接全量；IsAllJoin=false：按优先级排序后仍全量写入，供用户自主选择参与哪些活动

    var finalActList = entryAct.GroupIsAllJoin

        ? validActList

        : SortByPriority(validActList, \_initBizData.\_BrandObj.PayActivityPriorityType).ToList();



    // 5. 循环外统一清缓存（避免 N 次重复清）

    CrmActDeliverGroupOrderLogBll.ClearCache(brandId, request.VipId);



    // 6. 逐活动写新表 + 推消息（独立 try-catch，一个失败不影响其他）

    foreach (var act in finalActList)

    {

        try

        {

            ProcessGroupActResult(brandId, copId, request, act, entryAct.GroupId.Value);

        }

        catch (Exception ex)

        {

            // Duplicate Key 视为已写入，记录 Warn 后继续

            Log.Warn(\$"ProcessGroupActs: ActId={act.Id} 写入跳过，可能已存在。{ex.Message}");

        }

    }

}



/// <summary>

/// 单个分组活动：获取游戏链接、写新表 crm_act_deliver_group_order_log、推模板消息

/// </summary>

private void ProcessGroupActResult(

    int brandId, int copId,

    PayActivityPaySuccessJobRequest request,

    MpActDeliverReferencedInfo actModel,

    int groupId)

{

    int lotteryNum = CalcLotteryNum(request.SalesAmount, actModel);



    string defUrl, picUrl;

    GetActGameLink(brandId, request, actModel, lotteryNum, out defUrl, out picUrl);



    var orderLog = new CrmActDeliverGroupOrderLogInfo

    {

        BrandId    = brandId,

        CopId      = copId,

        VipId      = request.VipId,

        OrderId    = request.OrderId,

        ActId      = actModel.Id,

        ActName    = actModel.ActName,   // 冗余存储，避免C端展示时回查

        ActDeliverId = actModel.ActDeliverId,

        GroupId    = groupId,

        LotteryNum = lotteryNum,

        IsLuckDraw = 0,

        DoneLotteryNum = 0,

        ActDeliverReferencedLink   = defUrl,

        FullActBackgroundPicUrl    = picUrl,

        LogDayInt  = int.Parse(DateTime.Now.ToString("yyyyMMdd"))

    };

    CrmActDeliverGroupOrderLogBll.SaveOrderLog(orderLog);



    if (request.OrderType == 1)

    {

        SendTemplateMsg(brandId, request, defUrl);

    }

}



/// <summary>

/// 校验订单门店是否匹配活动配置的消费门店

/// </summary>

private bool IsShopMatch(string shopId, MpActDeliverReferencedInfo act)

{

    if (string.IsNullOrWhiteSpace(act.SalesShopIds))

        return true;

    return act.SalesShopIds.Split(',').Contains(shopId);

}

