public bool CheckActVipOrderChanceOnly(int brandId, PayActivityPaySuccessJobRequest request, MpActDeliverReferencedInfo actModel)

{

    var checkRequest = new CheckActVipOrderChanceRequestBusi()

    {

        CheckActVipOrderListRequest = new List<CrmActDeliverVipGetRequestBusi>

        {

            new CrmActDeliverVipGetRequestBusi()

            {

                BrandId = brandId,

                VipId = request.VipId,

                OrderId = request.OrderId,

                Type = request.OrderType == 0 ? "M" : "F",

                ActDeliverId = actModel.ActDeliverId

            }

        }

    };



    var response = actDeliverReferencedClient.CheckActVipOrderChance(checkRequest);

    var resultList = (response?.CheckActVipOrderResultList != null && response.CheckActVipOrderResultList.Any())

        ? response.CheckActVipOrderResultList.CopyListTo<CheckActVipOrderResult>()

        : null;

    if (resultList == null) return false;



    var result = resultList.Find(o => o.OrderId == request.OrderId);

