public class VipActStatsResult

{

    /// <summary>累计参与次数</summary>

    public int TotalCount { get; set; }

    /// <summary>今日参与次数</summary>

    public int TodayCount { get; set; }

}



public static VipActStatsResult GetVipActStats(int brandId, long vipId, int actId)

{

    int todayInt = int.Parse(DateTime.Now.ToString("yyyyMMdd"));

    using (var db = DbDaoFactory.GetOpenConnection(

        typeof(CrmActDeliverGroupOrderLogInfo), brandId, OperationType.Read))

    {

        var logs = db.GetAllSplitsDatas<CrmActDeliverGroupOrderLogInfo>(

            brandId,

            selectCols: o => new { o.LogDayInt },

            "BrandId = @BrandId AND VipId = @VipId AND ActId = @ActId",

            new { BrandId = brandId, VipId = vipId, ActId = actId });



        return new VipActStatsResult

        {

            TotalCount = logs?.Count ?? 0,

            TodayCount = logs?.Count(o => o.LogDayInt == todayInt) ?? 0

        };

    }

}

